def count_reachable_within_steps(graph: dict, start: str, max_steps: int) -> int:
    """
    Count how many distinct nodes are reachable from `start` in at most `max_steps` steps.
    The graph is an undirected adjacency dictionary where each key maps to a list of neighbors.

    Examples:
        count_reachable_within_steps({'A': ['B'], 'B': ['A', 'C'], 'C': ['B']}, 'A', 1) == 2
        count_reachable_within_steps({'A': ['B'], 'B': ['A', 'C'], 'C': ['B']}, 'A', 0) == 1
    """
    if start not in graph and max_steps < 0:
        return 0

    visited = {start}
    frontier = [start]

    for _ in range(max_steps):
        next_frontier = []
        for node in frontier:
            for neighbor in graph.get(node, []):
                if neighbor not in visited:
                    visited.add(neighbor)
                    next_frontier.append(neighbor)
        if not next_frontier:
            break
        frontier = next_frontier

    return len(visited)
