def min_enclosing_circle(points: list[tuple[float, float]]) -> tuple[float, float, float]:
    """Return the smallest enclosing circle of a set of 2D points.

    Returns (cx, cy, r) where (cx, cy) is the center and r the radius.
    Uses Welzl's randomized incremental algorithm.

    Examples:
        >>> round(min_enclosing_circle([(0,0),(2,0)])[2], 6)
        1.0
        >>> c = min_enclosing_circle([(0,0),(1,0),(0,1)]); round(c[2], 4)
        0.7071
    """
    import random

    def circle_from_two(a, b):
        cx = (a[0] + b[0]) / 2.0
        cy = (a[1] + b[1]) / 2.0
        r = ((a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2) ** 0.5 / 2.0
        return (cx, cy, r)

    def circle_from_three(a, b, c):
        ax, ay = a
        bx, by = b
        cx_, cy_ = c
        d = 2 * (ax * (by - cy_) + bx * (cy_ - ay) + cx_ * (ay - by))
        if abs(d) < 1e-12:
            # Collinear: pick the farthest pair
            pairs = [(a, b), (b, c), (a, c)]
            best = max(pairs, key=lambda p: (p[0][0] - p[1][0]) ** 2 + (p[0][1] - p[1][1]) ** 2)
            return circle_from_two(*best)
        ux = ((ax * ax + ay * ay) * (by - cy_) + (bx * bx + by * by) * (cy_ - ay) + (cx_ * cx_ + cy_ * cy_) * (ay - by)) / d
        uy = ((ax * ax + ay * ay) * (cx_ - bx) + (bx * bx + by * by) * (ax - cx_) + (cx_ * cx_ + cy_ * cy_) * (bx - ax)) / d
        r = ((ax - ux) ** 2 + (ay - uy) ** 2) ** 0.5
        return (ux, uy, r)

    def in_circle(c, p):
        return (p[0] - c[0]) ** 2 + (p[1] - c[1]) ** 2 <= c[2] * c[2] + 1e-9

    def welzl(pts, boundary):
        if not pts or len(boundary) == 3:
            if len(boundary) == 0:
                return (0.0, 0.0, -1.0)
            elif len(boundary) == 1:
                return (boundary[0][0], boundary[0][1], 0.0)
            elif len(boundary) == 2:
                return circle_from_two(boundary[0], boundary[1])
            else:
                return circle_from_three(boundary[0], boundary[1], boundary[2])

        p = pts[-1]
        rest = pts[:-1]
        c = welzl(rest, boundary)
        if c[2] >= 0 and in_circle(c, p):
            return c
        return welzl(rest, boundary + [p])

    pts = list(points)
    if not pts:
        return (0.0, 0.0, -1.0)
    if len(pts) == 1:
        return (pts[0][0], pts[0][1], 0.0)

    random.seed(42)
    shuffled = pts[:]
    random.shuffle(shuffled)

    # Iterative Welzl to avoid recursion depth issues
    c = (shuffled[0][0], shuffled[0][1], 0.0)
    for i in range(1, len(shuffled)):
        p = shuffled[i]
        if in_circle(c, p):
            continue
        c = (p[0], p[1], 0.0)
        for j in range(i):
            q = shuffled[j]
            if in_circle(c, q):
                continue
            c = circle_from_two(p, q)
            for k in range(j):
                r_pt = shuffled[k]
                if in_circle(c, r_pt):
                    continue
                c = circle_from_three(p, q, r_pt)
    return c
